using System.Text.Json.Serialization;

namespace TradeRecon.Application.Audit;

/// <summary>
/// Serialised form of a single append-only audit history entry. This is both the on-disk
/// ledger line and the exported entry, so what Compliance reads is exactly what was sealed.
/// </summary>
public sealed class AuditEntryDocument
{
    /// <summary>Global append order of the entry (1-based, gap-free).</summary>
    [JsonPropertyName("sequence")]
    public long Sequence { get; set; }

    /// <summary>Version of the request that this entry produced (1 = proposal).</summary>
    [JsonPropertyName("version")]
    public int Version { get; set; }

    /// <summary>Identity of the resolution request this entry belongs to.</summary>
    [JsonPropertyName("requestId")]
    public string RequestId { get; set; } = string.Empty;

    /// <summary>Lifecycle action: <c>Proposed</c>, <c>Approved</c> or <c>Rejected</c>.</summary>
    [JsonPropertyName("action")]
    public string Action { get; set; } = string.Empty;

    /// <summary>Alias of <see cref="Action"/> for readers keyed on lifecycle wording.</summary>
    [JsonPropertyName("lifecycleAction")]
    public string LifecycleAction { get; set; } = string.Empty;

    /// <summary>Recognised identity that performed the action.</summary>
    [JsonPropertyName("actor")]
    public string Actor { get; set; } = string.Empty;

    /// <summary>Capacity of the actor: <c>Proposer</c> or <c>Checker</c>.</summary>
    [JsonPropertyName("actorRole")]
    public string ActorRole { get; set; } = string.Empty;

    /// <summary>Recognised identity of the maker who raised the request.</summary>
    [JsonPropertyName("proposer")]
    public string Proposer { get; set; } = string.Empty;

    /// <summary>Recognised identity of the checker, once decided.</summary>
    [JsonPropertyName("approver")]
    public string? Approver { get; set; }

    /// <summary>Alias of <see cref="Approver"/>.</summary>
    [JsonPropertyName("checker")]
    public string? Checker { get; set; }

    /// <summary>Business date of the reconciliation break under resolution.</summary>
    [JsonPropertyName("businessDate")]
    public string BusinessDate { get; set; } = string.Empty;

    /// <summary>UTC instant the entry was sealed.</summary>
    [JsonPropertyName("timestamp")]
    public string Timestamp { get; set; } = string.Empty;

    /// <summary>Analyst narrative, redacted of identifiers and amounts.</summary>
    [JsonPropertyName("reason")]
    public string Reason { get; set; } = string.Empty;

    /// <summary>Digest of the original, unredacted reason.</summary>
    [JsonPropertyName("reasonDigest")]
    public string ReasonDigest { get; set; } = string.Empty;

    /// <summary>Supporting evidence reference, redacted of identifiers and amounts.</summary>
    [JsonPropertyName("evidence")]
    public string Evidence { get; set; } = string.Empty;

    /// <summary>Digest of the original, unredacted evidence.</summary>
    [JsonPropertyName("evidenceDigest")]
    public string EvidenceDigest { get; set; } = string.Empty;

    /// <summary>Digest of the reconciliation break key, when one was supplied.</summary>
    [JsonPropertyName("breakReference")]
    public string? BreakReference { get; set; }

    /// <summary>True when this entry is the terminal decision for its request.</summary>
    [JsonPropertyName("isFinalDecision")]
    public bool IsFinalDecision { get; set; }

    /// <summary>True when a decision was taken by someone other than the proposer.</summary>
    [JsonPropertyName("checkerDistinctFromProposer")]
    public bool? CheckerDistinctFromProposer { get; set; }

    /// <summary>Hash of the preceding entry; anchors this entry into the chain.</summary>
    [JsonPropertyName("previousHash")]
    public string PreviousHash { get; set; } = string.Empty;

    /// <summary>Hash sealing this entry's content and its link to the chain.</summary>
    [JsonPropertyName("entryHash")]
    public string EntryHash { get; set; } = string.Empty;
}

using System.Text.Json.Serialization;

namespace TradeRecon.Application.Audit;

/// <summary>
/// Per-request rollup included in the export so a reviewer can see, without replaying the
/// entries themselves, that a decided request has exactly one final decision and that the
/// checker is a different person from the proposer.
/// </summary>
public sealed class AuditRequestSummary
{
    [JsonPropertyName("requestId")]
    public string RequestId { get; set; } = string.Empty;

    [JsonPropertyName("businessDate")]
    public string BusinessDate { get; set; } = string.Empty;

    /// <summary>Current lifecycle state: <c>Pending</c>, <c>Approved</c> or <c>Rejected</c>.</summary>
    [JsonPropertyName("status")]
    public string Status { get; set; } = string.Empty;

    [JsonPropertyName("proposer")]
    public string Proposer { get; set; } = string.Empty;

    /// <summary>Deciding checker, when the request has been decided.</summary>
    [JsonPropertyName("checker")]
    public string? Checker { get; set; }

    /// <summary>Alias of <see cref="Checker"/>.</summary>
    [JsonPropertyName("approver")]
    public string? Approver { get; set; }

    /// <summary>Terminal action, when decided.</summary>
    [JsonPropertyName("finalDecision")]
    public string? FinalDecision { get; set; }

    /// <summary>Ledger sequence of the single durable final decision.</summary>
    [JsonPropertyName("finalDecisionSequence")]
    public long? FinalDecisionSequence { get; set; }

    /// <summary>Number of durable decision entries. Never exceeds one.</summary>
    [JsonPropertyName("decisionCount")]
    public int DecisionCount { get; set; }

    /// <summary>Total durable entries recorded for the request.</summary>
    [JsonPropertyName("entryCount")]
    public int EntryCount { get; set; }

    /// <summary>True when the request is decided by a checker distinct from its proposer.</summary>
    [JsonPropertyName("checkerDistinctFromProposer")]
    public bool CheckerDistinctFromProposer { get; set; }

    /// <summary>True when the maker-checker invariant holds for this request.</summary>
    [JsonPropertyName("segregationOfDutiesSatisfied")]
    public bool SegregationOfDutiesSatisfied { get; set; }
}

using System.Text.Json.Serialization;

namespace TradeRecon.Application.Audit;

/// <summary>
/// The Compliance export: an append-only slice of the audit history for a business-date range.
/// </summary>
public sealed class AuditExportDocument
{
    [JsonPropertyName("schemaVersion")]
    public string SchemaVersion { get; set; } = AuditContract.SchemaVersion;

    [JsonPropertyName("generatedAt")]
    public string GeneratedAt { get; set; } = string.Empty;

    [JsonPropertyName("fromDate")]
    public string FromDate { get; set; } = string.Empty;

    [JsonPropertyName("toDate")]
    public string ToDate { get; set; } = string.Empty;

    [JsonPropertyName("entryCount")]
    public int EntryCount { get; set; }

    [JsonPropertyName("requestCount")]
    public int RequestCount { get; set; }

    /// <summary>True when the whole persisted hash chain verified at export time.</summary>
    [JsonPropertyName("chainVerified")]
    public bool ChainVerified { get; set; }

    /// <summary>Hash of the head of the chain: a fingerprint of the entire history.</summary>
    [JsonPropertyName("ledgerHash")]
    public string LedgerHash { get; set; } = string.Empty;

    /// <summary>Declares that identifiers and amounts are redacted from all narrative fields.</summary>
    [JsonPropertyName("redaction")]
    public AuditRedactionNotice Redaction { get; set; } = new();

    /// <summary>The append-only history entries, in durable sequence order.</summary>
    [JsonPropertyName("entries")]
    public IReadOnlyList<AuditEntryDocument> Entries { get; set; } = [];

    /// <summary>Per-request rollup over <see cref="Entries"/>.</summary>
    [JsonPropertyName("requests")]
    public IReadOnlyList<AuditRequestSummary> Requests { get; set; } = [];
}

/// <summary>Describes the redaction guarantee applied to every exported narrative field.</summary>
public sealed class AuditRedactionNotice
{
    [JsonPropertyName("applied")]
    public bool Applied { get; set; } = true;

    [JsonPropertyName("policy")]
    public string Policy { get; set; } =
        "Account, instrument and record identifiers and all monetary or quantity amounts are "
        + "replaced with placeholders before persistence; only digests of the original text are kept.";

    [JsonPropertyName("identifierPlaceholder")]
    public string IdentifierPlaceholder { get; set; } = Domain.Audit.SensitiveTextRedactor.IdentifierPlaceholder;

    [JsonPropertyName("amountPlaceholder")]
    public string AmountPlaceholder { get; set; } = Domain.Audit.SensitiveTextRedactor.AmountPlaceholder;
}

