    }

    [Fact]
    public async Task HistorySurvivesAProcessRestart()
    {
        using var state = new AuditTestState();
        await state.Service.ProposeAsync(state.Proposal());
        await state.Service.DecideAsync(state.Decision());

        var reopened = new ResolutionWorkflowService(
            new Infrastructure.Audit.FileAuditLedger(state.Directory),
            new SteppingTimeProvider(new DateTimeOffset(2024, 6, 5, 9, 0, 0, TimeSpan.Zero)));

        var replay = await reopened.DecideAsync(state.Decision());
        var export = await reopened.ExportAsync(new ExportHistoryQuery
        {
            FromDate = new DateOnly(2024, 6, 3),
            ToDate = new DateOnly(2024, 6, 3)
        });

        Assert.True(replay.Ok);
        Assert.True(replay.Idempotent);
        Assert.Equal(2, export.Document!.EntryCount);
        Assert.True(export.Document.ChainVerified);
    }
