using TradeRecon.Application.Audit;
using TradeRecon.Domain.Audit;
using TradeRecon.Infrastructure.Audit;
using Xunit;

namespace TradeRecon.Tests;

public class AuditConcurrencyTests
{
    private static ResolutionWorkflowService NewService(string directory)
        => new(new FileAuditLedger(directory), TimeProvider.System);

    [Fact]
    public async Task ConcurrentConflictingDecisionsLeaveExactlyOneDurableFinalDecision()
    {
        using var state = new AuditTestState();
        await state.Service.ProposeAsync(state.Proposal());

        var contenders = new (string Approver, ResolutionDecision Decision)[]
        {
            ("checker.a", ResolutionDecision.Approved),
            ("checker.b", ResolutionDecision.Rejected),
            ("checker.c", ResolutionDecision.Approved),
            ("checker.d", ResolutionDecision.Rejected),
            ("checker.e", ResolutionDecision.Approved),
            ("checker.f", ResolutionDecision.Rejected),
            ("checker.g", ResolutionDecision.Approved),
            ("checker.h", ResolutionDecision.Rejected)
        };

        var results = await Task.WhenAll(contenders.Select(contender => Task.Run(() =>
            NewService(state.Directory).DecideAsync(new RecordDecisionCommand
            {
                RequestId = "REQ-001",
                Approver = contender.Approver,
                Decision = contender.Decision
            }))));

        var winners = results.Where(result => result.Ok).ToList();
        Assert.Single(winners);
        Assert.All(results.Where(result => !result.Ok),
            result => Assert.Equal(AuditErrorCodes.AlreadyDecided, result.ErrorCode));

        await using var transaction = await new FileAuditLedger(state.Directory).BeginAsync();
        Assert.True(transaction.ChainVerified);
        Assert.Equal(2, transaction.Entries.Count);
        var decisions = transaction.Entries.Where(entry => entry.IsFinalDecision).ToList();
        Assert.Single(decisions);
        Assert.Equal(winners[0].Entry!.EntryHash, decisions[0].EntryHash);
        Assert.True(decisions[0].CheckerIsDistinctFromProposer);
    }

    [Fact]
    public async Task ConcurrentRetriesOfTheSameProposalAppendOnlyOnce()
    {
        using var state = new AuditTestState();
        var command = state.Proposal();

        var results = await Task.WhenAll(Enumerable.Range(0, 8).Select(_ => Task.Run(() =>
            NewService(state.Directory).ProposeAsync(command))));

        Assert.All(results, result => Assert.True(result.Ok));
        Assert.Single(results.Where(result => !result.Idempotent));

        await using var transaction = await new FileAuditLedger(state.Directory).BeginAsync();
        Assert.True(transaction.ChainVerified);
        Assert.Single(transaction.Entries);
    }

    [Fact]
    public async Task ConcurrentWritesAcrossRequestsKeepTheChainContiguous()
    {
        using var state = new AuditTestState();

        var results = await Task.WhenAll(Enumerable.Range(1, 12).Select(index => Task.Run(() =>
            NewService(state.Directory).ProposeAsync(state.Proposal(
                requestId: $"REQ-{index:D3}",
                reason: $"Custodian confirmation batch {index} narrative.")))));

        Assert.All(results, result => Assert.True(result.Ok));

        await using var transaction = await new FileAuditLedger(state.Directory).BeginAsync();
        Assert.True(transaction.ChainVerified);
        Assert.Equal(12, transaction.Entries.Count);
        Assert.Equal(
            Enumerable.Range(1, 12).Select(index => (long)index).ToList(),
            transaction.Entries.Select(entry => entry.Sequence).ToList());
        Assert.Equal(12, transaction.Entries.Select(entry => entry.RequestId).Distinct(StringComparer.Ordinal).Count());
    }

    [Fact]
    public async Task ConcurrentSelfApprovalAttemptsNeverProduceADecision()
    {
        using var state = new AuditTestState();
        await state.Service.ProposeAsync(state.Proposal());

        var results = await Task.WhenAll(Enumerable.Range(0, 6).Select(index => Task.Run(() =>
            NewService(state.Directory).DecideAsync(new RecordDecisionCommand
            {
                RequestId = "REQ-001",
                Approver = index % 2 == 0 ? "analyst.one" : "ANALYST.ONE",
                Decision = ResolutionDecision.Approved
            }))));

        Assert.All(results, result =>
        {
            Assert.False(result.Ok);
            Assert.Equal(AuditErrorCodes.SelfApprovalNotPermitted, result.ErrorCode);
        });

        await using var transaction = await new FileAuditLedger(state.Directory).BeginAsync();
        Assert.Single(transaction.Entries);
        Assert.DoesNotContain(transaction.Entries, entry => entry.IsFinalDecision);
    }
}

using System.Text.Json;
using Xunit;

namespace TradeRecon.Tests;

public class AuditAdapterContractTests
{
    private static readonly string[] ShellExecutables =
        ["cmd", "cmd.exe", "sh", "bash", "zsh", "powershell", "powershell.exe", "pwsh", "pwsh.exe"];

    private static readonly char[] ShellMetacharacters = ['|', '&', ';', '>', '<', '`', '$', '\n'];

    public static TheoryData<string, string[]> RequiredPlaceholders => new()
    {
        { "initialize", ["{stateDirectory}"] },
        { "propose", ["{stateDirectory}", "{requestId}", "{proposer}", "{businessDate}", "{reason}", "{evidence}"] },
        { "decide", ["{stateDirectory}", "{requestId}", "{approver}", "{decision}"] },
        { "export", ["{stateDirectory}", "{fromDate}", "{toDate}", "{exportPath}"] }
    };

    [Fact]
    public void TheAuditAdapterSitsAtTheCandidateRootAndIsValidJson()
    {
        using var document = JsonDocument.Parse(File.ReadAllText(AuditAdapterPath));
        var root = document.RootElement;

        Assert.Equal(JsonValueKind.Object, root.ValueKind);
        Assert.False(string.IsNullOrWhiteSpace(root.GetProperty("schemaVersion").GetString()));
        Assert.False(string.IsNullOrWhiteSpace(root.GetProperty("workingDirectory").GetString()));
    }

    [Theory]
    [MemberData(nameof(RequiredPlaceholders))]
    public void EveryCommandIsAShellFreeArrayCarryingItsPlaceholders(string command, string[] placeholders)
    {
        using var document = JsonDocument.Parse(File.ReadAllText(AuditAdapterPath));
        var element = document.RootElement.GetProperty(command);

        var executable = element.GetProperty("executable").GetString();
        Assert.False(string.IsNullOrWhiteSpace(executable));
        Assert.DoesNotContain(executable!.ToLowerInvariant(), ShellExecutables);

        var arguments = element.GetProperty("arguments")
            .EnumerateArray()
            .Select(argument => argument.GetString() ?? string.Empty)
            .ToList();

        Assert.NotEmpty(arguments);
        Assert.All(arguments, argument => Assert.Equal(-1, argument.IndexOfAny(ShellMetacharacters)));

        foreach (var placeholder in placeholders)
        {
            Assert.Contains(placeholder, arguments);
        }

        var exitCodes = element.GetProperty("allowedExitCodes").EnumerateArray().Select(code => code.GetInt32());
        Assert.Contains(0, exitCodes);
    }

    [Fact]
    public void EveryPlaceholderIsItsOwnArgumentSoNoQuotingIsRequired()
    {
        using var document = JsonDocument.Parse(File.ReadAllText(AuditAdapterPath));

        foreach (var command in new[] { "initialize", "propose", "decide", "export" })
        {
            var arguments = document.RootElement
                .GetProperty(command)
                .GetProperty("arguments")
                .EnumerateArray()
                .Select(argument => argument.GetString() ?? string.Empty);

            foreach (var argument in arguments.Where(value => value.Contains('{', StringComparison.Ordinal)))
            {
                Assert.StartsWith("{", argument, StringComparison.Ordinal);
                Assert.EndsWith("}", argument, StringComparison.Ordinal);
                Assert.Equal(1, argument.Count(character => character == '{'));
            }
        }
    }

    [Fact]
    public void TheReconciliationAdapterContractIsPreserved()
    {
        var path = Path.Combine(RepositoryRoot, "benchmark-adapter.json");
        using var document = JsonDocument.Parse(File.ReadAllText(path));
        var root = document.RootElement;

        Assert.Equal("1.0.0", root.GetProperty("schemaVersion").GetString());
        foreach (var command in new[] { "build", "test", "run" })
        {
            Assert.True(root.TryGetProperty(command, out var element));
            Assert.Equal("dotnet", element.GetProperty("executable").GetString());
            Assert.NotEmpty(element.GetProperty("arguments").EnumerateArray());
        }

        var outputs = root.GetProperty("outputs").EnumerateArray().Select(output => output.GetString()).ToList();
        Assert.Contains("{businessDate}/eod-summary.txt", outputs);
        Assert.Contains("{businessDate}/eod-break-register.csv", outputs);
        Assert.Contains("{businessDate}/eod-result.json", outputs);
    }

    private static string AuditAdapterPath => Path.Combine(RepositoryRoot, "audit-adapter.json");

    private static string RepositoryRoot
    {
        get
